import com.google.crypto.tink.*;
import com.google.crypto.tink.streamingaead.StreamingAeadConfig;
import java.nio.file.*;
import java.io.*;
import java.security.MessageDigest;
import java.util.Arrays;

/** Reads ciphertext generated by the production Swift writer with REAL Tink,
 * then emits Tink ciphertext for the production Swift reader. Test keys only. */
public class TinkInterop {
    public static void main(String[] args) throws Exception {
        StreamingAeadConfig.register();
        try (var directories = Files.list(Path.of(args[0]))) {
            for (Path folder : directories.filter(Files::isDirectory).toList()) {
                var handle = CleartextKeysetHandle.read(BinaryKeysetReader.withBytes(Files.readAllBytes(folder.resolve("keyset"))));
                var aead = handle.getPrimitive(StreamingAead.class);
                byte[] expected = Files.readAllBytes(folder.resolve("plain"));
                try (var input = aead.newDecryptingStream(Files.newInputStream(folder.resolve("swift.enc")), new byte[0])) {
                    if (!Arrays.equals(expected, input.readAllBytes())) throw new AssertionError("Swift -> Tink mismatch " + folder);
                }
                try (var output = aead.newEncryptingStream(Files.newOutputStream(folder.resolve("tink.enc")), new byte[0])) {
                    output.write(expected);
                }
                Files.write(folder.resolve("tink.sha256"), MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(folder.resolve("tink.enc"))));
            }
        }
        System.out.println("PASS: production Swift ciphertext read by Tink; reverse fixtures generated");
    }
}
